const express = require('express');
const { Scalekit } = require('@scalekit-sdk/node');

const app = express();

// Initialize Scalekit client
// These should be configured via environment variables
const scalekit = new Scalekit({
  issuerUrl: process.env.SCALEKIT_ISSUER_URL || 'https://auth.scalekit.dev',
  clientId: process.env.SCALEKIT_CLIENT_ID || 'your-client-id',
  clientSecret: process.env.SCALEKIT_CLIENT_SECRET || 'your-client-secret',
});

// Authentication middleware
const authMiddleware = async (req, res, next) => {
  try {
    // Extract the Bearer token from the Authorization header
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Missing or invalid Authorization header. Expected format: Bearer <token>'
      });
    }

    const token = authHeader.substring(7); // Remove 'Bearer ' prefix

    // Validate the token and check for required scopes
    const validation = await scalekit.validateToken(token, {
      requiredScopes: ['todo:read']
    });

    if (!validation.isValid) {
      if (validation.error === 'insufficient_scope') {
        return res.status(403).json({
          error: 'Forbidden',
          message: 'Token does not have the required scope: todo:read'
        });
      }

      return res.status(401).json({
        error: 'Unauthorized',
        message: validation.error || 'Invalid token'
      });
    }

    // Attach token info to request for use in route handlers
    req.user = validation.payload;
    next();
  } catch (error) {
    console.error('Authentication error:', error);
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Failed to validate token'
    });
  }
};

// Sample todos data
const todos = [
  { id: 1, title: 'Complete project documentation', completed: false },
  { id: 2, title: 'Review pull requests', completed: true },
  { id: 3, title: 'Update dependencies', completed: false },
  { id: 4, title: 'Write unit tests', completed: false },
  { id: 5, title: 'Deploy to production', completed: true }
];

// Protected GET /todos endpoint
app.get('/todos', authMiddleware, (req, res) => {
  res.json({
    success: true,
    data: todos,
    count: todos.length
  });
});

// Health check endpoint (no authentication required)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    message: 'Server is running'
  });
});

// Start the server
const PORT = process.env.PORT || 3001;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
  console.log(`GET /health - Health check endpoint`);
  console.log(`GET /todos - Protected endpoint (requires Bearer token with todo:read scope)`);
});

